def find_note(notes, note_id):
    return next(note for note in notes if note["id"] == note_id)

def read_note(notes, note_id, caller):
    return find_note(notes, note_id)

def update_note(notes, note_id, caller, text):
    note = find_note(notes, note_id)
    if note["owner_id"] != caller:
        raise PermissionError("denied")
    note["text"] = text
    return note

