from contextlib import contextmanager


class NotesStore:
    def __init__(self, path):
        self._db = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self._db.execute("PRAGMA busy_timeout = 5000")
        self._lock = threading.RLock()
        with self._lock:
            self._db.execute("PRAGMA foreign_keys = ON")
            self._db.execute(
                "CREATE TABLE IF NOT EXISTS notes ("
                "id INTEGER PRIMARY KEY, "
                "owner_id TEXT NOT NULL, "
                "request_id TEXT NOT NULL, "
                "text TEXT NOT NULL, "
                "UNIQUE(owner_id, request_id))"
            )

    @staticmethod
    def _valid(text):
        if not isinstance(text, str) or not text.strip():
            raise ValueError("blank text")
        return text

    @staticmethod
    def _note(row):
        return {"id": row[0], "owner_id": row[1], "text": row[2]}

    @contextmanager
    def _transaction(self):
        self._db.execute("BEGIN IMMEDIATE")
        try:
            yield
        except Exception:
            self._db.execute("ROLLBACK")
            raise
        else:
            self._db.execute("COMMIT")

    def create(self, caller, request_id, text):
        with self._lock, self._transaction():
            row = self._db.execute(
                "SELECT id, owner_id, text FROM notes "
                "WHERE owner_id = ? AND request_id = ?", (caller, request_id)
            ).fetchone()
            if row is not None:
                return self._note(row)
            self._valid(text)
            try:
                cursor = self._db.execute(
                    "INSERT INTO notes(owner_id, request_id, text) VALUES (?, ?, ?)",
                    (caller, request_id, text),
                )
            except sqlite3.IntegrityError:
                row = self._db.execute(
                    "SELECT id, owner_id, text FROM notes "
                    "WHERE owner_id = ? AND request_id = ?", (caller, request_id)
                ).fetchone()
                if row is not None:
                    return self._note(row)
                raise
