    def read(self, caller, note_id):
        with self._lock:
            row = self._db.execute(
                "SELECT id, owner_id, text FROM notes WHERE id = ? AND owner_id = ?",
                (note_id, caller),
            ).fetchone()
            if row is None:
                raise PermissionError("note unavailable")
            return self._note(row)

    def update(self, caller, note_id, text):
