            row = self._db.execute(
                "SELECT id, owner_id, text FROM notes WHERE id = ? AND owner_id = ?",
                (note_id, caller),
            ).fetchone()
            if row is None:
                raise PermissionError("note unavailable")
            self._valid(text)
            self._db.execute("UPDATE notes SET text = ? WHERE id = ?", (text, note_id))
            return {"id": note_id, "owner_id": caller, "text": text}

    def close(self):
        with self._lock:
            self._db.close()

